describe('Product Detail Page Navigation', () => {
  beforeEach(() => {
    cy.visit('/login');
    cy.get('[data-testid="username"]').type('standard_user');
    cy.get('[data-testid="password"]').type('secret_sauce');
    cy.get('[data-testid="login-button"]').click();
    cy.get('[data-testid="page-wrapper"]').should('be.visible');
  });

  it('should navigate to product detail page and return to catalogue on back button click', () => {
    // Verify login was successful
    cy.get('[data-testid="header-container"]').should('contain', 'Welcome, standard_user');

    // Click first product name to navigate to detail page
    cy.get('[data-testid="inventory-item-name"]').first().click();
    cy.url().should('include', '/inventory-item.html');

    // Verify product detail page is loaded
    cy.get('[data-testid="inventory-item-title"]').should('contain', 'Product Name');

    // Click back button to return to catalogue
    cy.get('[data-testid="back-to-products"]').click();
    cy.url().should('include', '/inventory.html');

    // Verify catalogue is visible
    cy.get('[data-testid="primary-header"]').should('contain', 'Products');
  });

  it('should handle edge case: back button returns to login page when at root', () => {
    // Verify login was successful
    cy.get('[data-testid="header-container"]').should('contain', 'Welcome, standard_user');

    // Click back button when at root
    cy.get('[data-testid="back-to-products"]').click();

    // Verify login page is displayed
    cy.get('[data-testid="header-container"]').should('contain', 'Welcome, standard_user');
    cy.get('[data-testid="page-wrapper"]').should('not.exist');
  });
});
